<section class="section dashboard-page"><div class="container"><a class="back-link" href="<?= e(url('admin/customers')) ?>">&larr; Customers</a><div class="page-heading"><div><span class="eyebrow">Customer profile</span><h1><?= e($customer['name']) ?></h1><p class="muted"><?= e($customer['email']) ?> · <?= e($customer['phone']) ?></p></div><span class="status-badge status-<?= e($customer['account_status']) ?>"><?= e($customer['account_status']) ?></span></div>
